(57, 18, '2026-06-15', 'Ni Nyoman Murti, AMd.Keb., M.Pd', 'OBSTETRI', 'https://docs.google.com/document/d/1TAPrBez8IK1D9IOAcvi4YgcuASva7EUBis3y6hJnPUY/edit?tab=t.0', 'Selesai', 'Berikut hasil revisi layoutnya  Catatan Layout 26-05-107-Obstetri  1. Tabel 2.1 belum ada caption 2. Banyak sisipan huruf i dalam paragraph Bab 12', '2026-06-15 15:02:34', '2026-06-18 16:58:23'),
(58, 18, '2026-06-15', 'HJ. ROSTIN', 'PERTUMBUHAN EKONOMI INKLUSIF SULAWESI TENGGARA', 'https://docs.google.com/document/d/1Ll8XX3V1sfQxr46FbQNe2K59kEVNyemWu5I2it1c2Ss/edit?tab=t.0#heading=h.dq2dub16mql1', 'Selesai', 'Izin menginformasikan untuk naskah baru *Pertumbuhan Ekonomi Inklusif Sulawesi Tenggara* setelah kami cek cukup rawan bermasalah saat ISBN karena beberapa bagian masih berformat hasil penelitan, oleh karena itu perlu ada revisi pada naskahnya. Berikut kami kirimkan naskah yang sudah kami berikan komentar pada bagian yang perlu diperbaiki. Kami tunggu konfirmasi selanjutnya. Terimakasih', '2026-06-15 15:04:46', '2026-06-19 15:17:24'),
(59, 18, '2026-06-18', 'Wahyuni Dyah Parmasari drg., Sp.Ort.', 'HOMEOSTASIS DAN FUNGSI RONGGA MULUT', 'https://docs.google.com/document/d/1LcicIAsm5auxA_MDGXsOQPCLktfKfrFJWIezauYNx8g/edit?tab=t.0#heading=h.ebmjcxqkahf', 'Selesai', 'pada bab 17 halaman 264 terdapat rumus yang tidak terdeteksi di word', '2026-06-18 09:31:24', '2026-06-18 10:22:36'),
