INSERT INTO `work_progresses` (`id`, `attendance_id`, `description`, `created_at`, `updated_at`) VALUES
(182, 444, 'Revisi Final Buku Perawatan Luka Diabetes Melitus - Gambar kurang jelas: 1.2, 15.1, 17.1\r\n- belum ada daftar pustaka bab 15', '2026-08-19 16:55:47', '2026-08-19 16:55:47'),
(183, 448, '1. Menganalisis ulang manuscript berdasarkan ketentuan terbaru Annals of Laboratory Medicine (ALM).\r\n2. Memfinalisasi blinded main manuscript untuk area Diagnostic Genetics.\r\n3. Melengkapi detail clinical and biochemical measurements, termasuk manufacturer dan lokasi alat laboratorium.\r\n4. Menyesuaikan penggunaan SI units pada fasting glucose, insulin, C-peptide, dan HOMA-IR.\r\n5. Memperbaiki pelaporan HbA1c menjadi dual reporting mmol/mol dan %.\r\n6. Melengkapi metode PCR dengan T100 Thermal Cycler, Bio-Rad.\r\n7. Melengkapi metode Sanger sequencing melalui 1st BASE dan platform Applied Biosystems.\r\n8. Menambahkan genome assembly GRCh38.p14 dan nomenklatur HGVS NC_000010.11:g.113049143G>T.\r\n9. Memperbaiki dan menyelaraskan nilai C-peptide pada Results dan Table 3.\r\n10. Memperbaiki format confidence interval dan P value agar konsisten.\r\n11. Memfinalisasi format Table 1–4.\r\n12. Memfinalisasi format References sesuai gaya ALM/Vancouver.\r\n13. Membersihkan metadata personal pada blinded manuscript menggunakan Document Inspector.\r\n14. Memastikan tidak ada comments, tracked changes, atau informasi identitas pada blinded manuscript.\r\n15. Menyiapkan Figure 1 Sanger chromatogram sebagai separate file 300 dpi.\r\n16. Menganalisis ketentuan Before You Submit ALM, termasuk ethics, authorship, conflict of interest, funding, duplicate publication, preprint, dan AI policy.', '2026-08-19 16:58:32', '2026-08-19 16:58:32'),
(184, 444, 'Revisi Final Buku Pencemaran Lingkungan Tabel kurang jelas: 6.1', '2026-08-19 17:00:52', '2026-08-19 17:00:52'),
(185, 453, 'Menginput Buku terbit tahun 2022-2023', '2026-08-20 16:00:36', '2026-08-20 16:00:36'),
(186, 451, 'proses dokumen submit manuscript pak agus limanto', '2026-08-20 18:15:06', '2026-08-20 18:15:06'),
(187, 452, '1. Menyiapkan dan memeriksa Title Page untuk submission ke Annals of Laboratory Medicine (ALM).\r\n2. Menyiapkan Blinded Main Manuscript sesuai kebutuhan proses peer review.\r\n3. Menyiapkan Cover Letter untuk ALM.\r\n4. Menyiapkan Figure 1 Sanger sequencing chromatograms sebagai file terpisah dengan resolusi 300 dpi.\r\n5. Memeriksa kesesuaian judul, running title, abstract, keywords, jumlah tabel, figure, dan word count.\r\n6. Memeriksa dan melengkapi Author Contributions/CRediT roles untuk seluruh penulis.\r\n7. Memeriksa bagian Funding, Conflict of Interest, Ethics Approval, Informed Consent, dan Acknowledgements.\r\n8. Memastikan informasi IRB/ethical approval sesuai dengan dokumen penelitian.\r\n9. Melakukan pengecekan blinding manuscript agar identitas author dan acknowledgement tidak tercantum dalam main document.\r\n10. Menyiapkan informasi suggested reviewers yang relevan dengan bidang Diagnostic Genetics dan T2DM.\r\n11. Melakukan submit manuscript', '2026-08-20 18:28:39', '2026-08-20 18:28:39'),
(188, 456, 'submit manuscript pak agus limanto', '2026-08-21 17:41:54', '2026-08-21 17:41:54'),
(189, 455, 'Menginput buku terbit tahun 2024, menambahkan gambar di bab 1, dan menganalisis cara penyusunan modul panduan praktikum keperawatan', '2026-08-21 18:34:51', '2026-08-21 18:34:51'),
(190, 454, 'Merevisi manuscript Ibu Ariyati Yosi', '2026-08-21 19:09:19', '2026-08-21 19:09:19'),
(191, 462, '1. Meninjau komentar editor terkait kewajiban menambahkan minimal 10 artikel relevan dari Research Journal of Pharmacy and Technology (RJPT).\r\n2. Memeriksa kesesuaian manuscript dengan Author Guidelines RJPT.\r\n3. Mengecek dan memperbaiki bagian referensi yang sebelumnya tertulis “[Reference withheld during peer review]”.\r\n4. Mengembalikan referensi asli No. 8 dan 9 ke dalam daftar pustaka.\r\n5. Memperbaiki urutan penomoran referensi agar Porasar et al. kembali menjadi Referensi No. 10.\r\n6. Memastikan seluruh referensi No. 1–35 tersusun secara konsisten.\r\n7. Memastikan 10 artikel RJPT yang diminta editor telah dimasukkan sebagai Referensi No. 26–35.\r\n8. Memeriksa kesesuaian sitasi artikel RJPT pada bagian Introduction dan Discussion.\r\n9. Melakukan pengecekan akhir revised manuscript setelah perbaikan referensi dan sitasi.\r\n10. Memastikan manuscript telah memenuhi komentar editor dan siap untuk proses pengiriman revisi.\r\n11. Mengecek keputusan terbaru dari Malaysian Journal of Medical Sciences (MJMS) terhadap manuscript “Complications, Risk Factors, and Quality of Life after Intestinal Stoma Formation: A Systematic Review and Meta-Analysis.”\r\n12. Membaca dan memahami komentar rejection dari editor/reviewer MJMS.\r\n13. Mengidentifikasi poin utama penyebab rejection, terutama terkait kelemahan metodologi meta-analysis, heterogenitas outcome, belum adanya risk-of-bias assessment, serta ketidaksesuaian data pada Table', '2026-08-22 15:16:40', '2026-08-22 15:16:40'),
